import { useState } from "react";
import "./App.css";

function App() {
  const [query, setQuery] = useState("");
  const [result, setResult] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleResearch = async () => {
    if (!query.trim()) return;
    setLoading(true);
    setResult("");
    setError("");

    try {
      const response = await fetch("http://127.0.0.1:8000/research", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query }),
      });
      const data = await response.json();
      if (data.status === "success") {
        setResult(data.result);
      } else {
        setError("Something went wrong. Please try again.");
      }
    } catch (err) {
      setError("Cannot connect to backend. Make sure it is running.");
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter") handleResearch();
  };

  return (
    <div className="app">
      <div className="container">
        <div className="header">
          <h1>Agentic Research Assistant</h1>
          <p>Powered by LangChain · LangGraph · Groq · Tavily</p>
        </div>

        <div className="search-box">
          <input
            type="text"
            placeholder="Ask me anything..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            disabled={loading}
          />
          <button onClick={handleResearch} disabled={loading || !query.trim()}>
            {loading ? "Researching..." : "Research"}
          </button>
        </div>

        {loading && (
          <div className="loading">
            <div className="spinner"></div>
            <p>Agent is researching the web for you...</p>
          </div>
        )}

        {error && <div className="error">{error}</div>}

        {result && (
          <div className="result">
            <h2>Research Result</h2>
            <p>{result}</p>
          </div>
        )}

        {!result && !loading && (
          <div className="examples">
            <p>Try asking:</p>
            <span onClick={() => setQuery("What is Agentic AI?")}>
              What is Agentic AI?
            </span>
            <span onClick={() => setQuery("Latest trends in AI 2026")}>
              Latest trends in AI 2026
            </span>
            <span onClick={() => setQuery("How does LangGraph work?")}>
              How does LangGraph work?
            </span>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
